typed_words = ["Hello", "World", "Pakistan"]
undo_presses = 1

actions = list()                          # the undo stack
for word in typed_words:
    actions.append(word)                  # every action is pushed
print("Document:", " ".join(actions))
for i in range(undo_presses):
    if actions:
        print("Undo removes:", actions.pop())
print("Document now:", " ".join(actions))

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[-1]


plates = Stack()
for plate in ["Plate 1", "Plate 2", "Plate 3"]:
    plates.push(plate)
    print("Stack:", plates.items)
removed = plates.pop()
print("Removed:", removed, "Stack:", plates.items)
print("Top plate:", plates.peek())
